after.css:
.proto .muted{color:var(--muted)}
.proto .u-bar{display:flex;align-items:center;justify-content:space-between;height:36px;padding:0 14px;background:var(--brand-tint);color:var(--brand);font:600 12.5px/1 var(--f-body);letter-spacing:.01em}
.proto .u-bar svg{opacity:.65}
.proto .logo{height:30px;width:auto}
.proto .t-insp{display:inline-flex;align-items:center;gap:7px;height:30px;padding:0 12px 0 10px;border:1.5px solid var(--brand);border-radius:999px;color:var(--brand);font:500 13px/1 var(--f-body)}
.proto .t-insp b{font-weight:700}
.proto .t-name{font-family:var(--f-display);font-weight:800;font-stretch:72%;text-transform:uppercase;letter-spacing:-.005em;line-height:.9;margin-top:14px;color:var(--ink)}
.proto .t-sub{font-size:14px;color:var(--ink-2);margin-top:8px}
.proto .t-desc{margin-top:12px;color:var(--ink)}
.proto .t-rate{display:flex;align-items:center;gap:8px;margin-top:12px;font-size:13px}
.proto .stars{display:inline-flex;color:#d99a00;gap:1px}
.proto .t-price{display:flex;align-items:baseline;flex-wrap:wrap;gap:6px 10px;margin-top:14px;font-variant-numeric:tabular-nums}
.proto .now{font:700 26px/1 var(--f-body);letter-spacing:-.01em}
.proto .was{color:var(--muted);text-decoration:line-through;font-size:15px}
.proto .save{align-self:center;background:var(--brand);color:#fff;font:700 11.5px/1 var(--f-body);padding:5px 7px;border-radius:3px;letter-spacing:.02em}
.proto .unit{margin-left:auto;font-size:13px;color:var(--muted)}
.proto .fine{font-size:12px;color:var(--muted);margin-top:4px}
.proto .ph{--ph-bg:var(--ph);border-radius:4px}
.proto .ph.vid{--ph-ar:9/16}
.proto .ph.vid .play{position:absolute;left:50%;top:42%;width:40px;height:40px;transform:translate(-50%,-50%);color:#fff;filter:drop-shadow(0 2px 6px rgba(0,0,0,.25))}
.proto .spec{display:grid;grid-template-columns:repeat(3,1fr);border-top:2px solid var(--ink);border-bottom:1px solid var(--line)}
.proto .spec div{padding:12px 0 12px 12px}
.proto .spec div:first-child{padding-left:0}
.proto .spec div+div{border-left:1px solid var(--line)}
.proto .spec b{display:block;font-family:var(--f-display);font-weight:800;font-stretch:72%;font-size:28px;line-height:1;text-transform:uppercase}
.proto .spec span{display:flex;gap:5px;align-items:center;font-size:12px;color:var(--muted);margin-top:6px}
.proto .o-label{display:flex;justify-content:space-between;align-items:baseline;font-size:14px}
.proto .o-label b{font-weight:700}
.proto .o-label a{font-size:13px;text-decoration:underline;text-underline-offset:3px;color:var(--ink-2)}
.proto .sizes{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:12px}
.proto .size{position:relative;border:1px solid var(--line);border-radius:6px;padding:13px 11px 11px;min-height:86px;display:flex;flex-direction:column;gap:3px;font-variant-numeric:tabular-nums;background:var(--bg)}
.proto .size b{font:700 16px/1.15 var(--f-body)}
.proto .size .p{font-size:14px}
.proto .size .pm{font-size:12px;color:var(--muted)}
.proto .size.on{border:2px solid var(--ink);padding:12px 10px 10px;background:var(--surface)}
.proto .size .tag{position:absolute;top:-9px;left:10px;background:var(--amber);color:#3a2700;font:700 10.5px/1 var(--f-body);padding:4px 6px;border-radius:3px;letter-spacing:.02em}
.proto .try{display:flex;gap:8px;align-items:flex-start;margin-top:14px;font-size:13.5px;color:var(--ink-2)}
.proto .try svg{color:var(--brand);margin-top:2px}
.proto .try a,.proto .offer a,.proto .assure a{color:var(--brand);font-weight:700;text-decoration:underline;text-underline-offset:3px}
.proto .offer{background:var(--brand-tint);border-radius:6px;padding:2px 14px}
.proto .offer li{display:flex;gap:11px;padding:11px 0;font-size:13.5px;line-height:1.45}
.proto .offer li+li{border-top:1px dashed rgba(135,40,36,.28)}
.proto .offer svg{color:var(--brand);margin-top:2px}
.proto .offer b{display:block;font-weight:700;color:var(--ink)}
.proto .code{font:700 12.5px/1.6 ui-monospace,Menlo,monospace;letter-spacing:.04em;border:1px dashed var(--brand);border-radius:4px;padding:0 6px;background:#fff;color:var(--brand)}
.proto .engr{display:flex;gap:12px;align-items:center;border:1px solid var(--line);border-radius:6px;padding:12px 14px;min-height:60px}
.proto .engr .box{width:20px;height:20px;border:1.5px solid var(--ink);border-radius:4px;flex:none}
.proto .engr b{display:block;font-size:14px;font-weight:700}
.proto .engr small{display:block;font-size:12px;color:var(--muted);margin-top:1px}
.proto .engr svg{margin-left:auto}
.proto .buy{display:flex;gap:8px}
.proto .qty{display:flex;align-items:center;border:1px solid var(--line);border-radius:6px;height:52px;font:600 16px/1 var(--f-body)}
.proto .qty button{width:42px;height:100%;display:grid;place-items:center}
.proto .qty span{min-width:18px;text-align:center}
.proto .buy .cta{flex:1;height:52px;background:var(--cta);color:var(--on-cta);border-radius:6px;font:700 16px/1 var(--f-body);letter-spacing:.01em}
.proto .buy2{width:100%;height:48px;border:1.5px solid var(--ink);border-radius:6px;font:600 15px/1 var(--f-body);display:flex;align-items:center;justify-content:center;gap:6px}
.proto .buy2 small{font-weight:500;color:var(--muted);font-size:13px}
.proto .assure{display:flex;flex-direction:column;gap:11px;font-size:14px}
.proto .assure li{display:flex;gap:10px;align-items:center}
.proto .assure svg{color:var(--muted)}
.proto .notes{background:var(--surface);border-radius:8px;padding:20px 18px 18px}
.proto .notes h3,.proto .vids-h{font-family:var(--f-display);font-weight:800;font-stretch:72%;text-transform:uppercase;font-size:24px;line-height:1;letter-spacing:.005em}
.proto .tier{display:grid;grid-template-columns:62px 1fr;align-items:baseline;padding:11px 0;border-top:1px solid var(--line);font-size:15px}
.proto .notes h3+.tier{margin-top:14px}
.proto .tier span{font:700 11px/1 var(--f-body);letter-spacing:.09em;text-transform:uppercase;color:var(--brand)}
.proto .accords{display:flex;flex-wrap:wrap;gap:6px;margin-top:12px}
.proto .accords em{font-style:normal;font-size:12.5px;border:1px solid var(--line);background:var(--bg);border-radius:999px;padding:4px 10px}
.proto .faq{border-top:1px solid var(--line)}
.proto .faq details{border-bottom:1px solid var(--line)}
.proto .faq summary{list-style:none;min-height:56px;display:flex;align-items:center;justify-content:space-between;gap:12px;font:600 15.5px/1.3 var(--f-body);cursor:pointer}
.proto .faq summary::-webkit-details-marker{display:none}
.proto .faq details[open] summary svg{transform:rotate(180deg)}
.proto .faq summary svg{transition:transform .2s ease-out}
.proto .faq .a{padding:0 0 16px;font-size:14.5px;color:var(--ink-2);max-width:62ch}
.proto .vids{display:flex;gap:10px;overflow:hidden}

desktop.css:
.proto[data-dev="desktop"]{padding-bottom:96px}
.proto[data-dev="desktop"] .u-bar{justify-content:center;gap:28px;font-size:13px}
.proto .d-hdr{display:grid;grid-template-columns:1fr auto 1fr;align-items:center;height:72px;padding:0 40px;background:var(--brand);color:#fff}
.proto .d-hdr .logo{height:38px}
.proto .d-hdr .r{display:flex;justify-content:flex-end;gap:6px}
.proto .d-hdr button{width:44px;height:44px;display:grid;place-items:center}
.proto .d-nav{display:flex;justify-content:center;gap:44px;height:54px;align-items:center;border-bottom:1px solid var(--line);font:600 13px/1 var(--f-body);letter-spacing:.07em;text-transform:uppercase}
.proto .d-main{max-width:1200px;margin:0 auto;padding:36px 40px 0;display:grid;grid-template-columns:minmax(0,1.12fr) minmax(0,1fr);gap:56px;align-items:start}
.proto .d-gal{display:grid;grid-template-columns:1fr 1fr;gap:12px}
.proto .d-gal .ph{--ph-ar:4/5;padding:18px}
.proto .d-gal .ph:first-child{grid-column:1/-1;--ph-ar:1/1}
.proto .d-gal .ph .ph-t{font-size:14px}
.proto .d-buy{position:sticky;top:24px;display:flex;flex-direction:column;gap:22px}
.proto .d-buy .tb{padding:0}
.proto[data-dev="desktop"] .t-name{font-size:88px}
.proto[data-dev="desktop"] .t-sub{font-size:15px}
.proto[data-dev="desktop"] .t-desc{font-size:17px;max-width:44ch}
.proto[data-dev="desktop"] .now{font-size:30px}
.proto[data-dev="desktop"] .d-buy .buy2{margin-top:-14px}
.proto .d-more{max-width:1200px;margin:72px auto 0;padding:0 40px;display:grid;grid-template-columns:1fr 1.25fr;gap:56px;align-items:start}
.proto .d-vids{max-width:1200px;margin:72px auto 0;padding:0 40px}
.proto .d-vids .vids-h{margin-bottom:18px}
.proto .d-vids .vids .ph{flex:1 1 0}
